using ClinicaEsteticaWeb.Models;using ClinicaEsteticaWeb.Services;using MySqlConnector;using Microsoft.AspNetCore.Mvc;
namespace ClinicaEsteticaWeb.Controllers;
public class UsuariosController:Controller {private readonly Db _db;public UsuariosController(Db db)=>_db=db;public IActionResult Index(){var l=new List<Usuario>();using var x=_db.Open();using var c=new MySqlCommand("SELECT id,nome,login,perfil,status FROM usuario ORDER BY nome",x);using var r=c.ExecuteReader();while(r.Read())l.Add(new Usuario{Id=r.GetInt32("id"),Nome=r.GetString("nome"),Login=r.GetString("login"),Perfil=r.GetString("perfil"),Status=r.GetString("status")});return View(l);}[HttpGet]public IActionResult Create()=>View(new Usuario{Perfil="recepcionista",Status="ativo"});[HttpPost][ValidateAntiForgeryToken]public IActionResult Create(Usuario u){if(string.IsNullOrWhiteSpace(u.Senha)){ModelState.AddModelError("Senha","Informe a senha.");return View(u);}using var x=_db.Open();using var c=new MySqlCommand("INSERT INTO usuario(nome,login,senha_hash,perfil,status,tentativas_falhas) VALUES(@n,@l,@s,@p,@st,0)",x);c.Parameters.AddWithValue("@n",u.Nome);c.Parameters.AddWithValue("@l",u.Login);c.Parameters.AddWithValue("@s",BCrypt.Net.BCrypt.HashPassword(u.Senha));c.Parameters.AddWithValue("@p",u.Perfil);c.Parameters.AddWithValue("@st",u.Status??"ativo");try{c.ExecuteNonQuery();return RedirectToAction(nameof(Index));}catch(MySqlException ex){ModelState.AddModelError("",ex.Message);return View(u);}}}
